class Solution {
public:
    int shortestSubarray(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> P(n + 1, 0);
        for (int i = 0; i < n; i++) {
            P[i + 1] = P[i] + nums[i];
        }
        deque<int> dq;
        int ans = n + 1;
        for (int j = 0; j <= n; j++) {
            while (!dq.empty() && P[j] - P[dq.front()] >= k) {
                int i = dq.front();
                dq.pop_front();
                if (j - i < ans) ans = j - i;
            }
            while (!dq.empty() && P[dq.back()] >= P[j]) {
                dq.pop_back();
            }
            dq.push_back(j);
        }
        return ans <= n ? ans : -1;
    }
};
